import React from 'react'

function ReviewsSection() {
    return (
        <div className="reviews w-full min-h-[510px] flex justify-center items-start py-10">
            <div className="w-[90%] min-h-[450px] bg-gray-100 rounded-lg p-6">
                <div className="w-full min-h-[70px] grid grid-cols-2 gap-4">
                    <div className="p-4 rounded-lg flex justify-start"><h2 className='font-medium text-3xl'>What our customers say!</h2></div>
                    <div className="p-4 rounded-lg flex justify-end">Rated 4.7 / 5 based on 28,370 reviews Showing our 4 & 5 star reviews</div>
                </div>
            </div>
        </div>
    )
}

export default ReviewsSection;
